"""Expression tree nodes and structural helpers."""


class Node:
    """A generic expression node.

    ``kind`` selects the node type and the remaining attributes hold its
    fields.  ``start`` and ``end`` are offsets into the original query text
    and are used to reproduce an expression exactly for output naming.
    """

    def __init__(self, kind, start=0, end=0, **fields):
        self.kind = kind
        self.start = start
        self.end = end
        for name, value in fields.items():
            setattr(self, name, value)

    def __repr__(self):  # pragma: no cover - debugging aid
        fields = ", ".join(
            "%s=%r" % (key, value)
            for key, value in self.__dict__.items()
            if key not in ("kind", "start", "end")
        )
        return "Node(%r, %s)" % (self.kind, fields)


def children(node):
    """Yield the direct child nodes of ``node``."""
    for name, value in node.__dict__.items():
        if name in ("kind", "start", "end"):
            continue
        if isinstance(value, Node):
            yield value
        elif isinstance(value, (list, tuple)):
            for item in value:
                if isinstance(item, Node):
                    yield item


def contains_agg(node):
    """Return True if ``node`` contains an aggregate function."""
    if node is None:
        return False
    if node.kind == "agg":
        return True
    return any(contains_agg(child) for child in children(node))


def ast_key(node):
    """A hashable structural key, ignoring source positions."""
    kind = node.kind
    if kind == "lit":
        value = node.value
        return ("lit", type(value).__name__, value)
    if kind == "col":
        return ("col", node.name.casefold())
    if kind == "paren":
        return ast_key(node.inner)
    if kind == "neg":
        return ("neg", ast_key(node.operand))
    if kind == "not":
        return ("not", ast_key(node.operand))
    if kind in ("and", "or"):
        return (kind, ast_key(node.left), ast_key(node.right))
    if kind == "bin":
        return ("bin", node.op, ast_key(node.left), ast_key(node.right))
    if kind == "cmp":
        return ("cmp", node.op, ast_key(node.left), ast_key(node.right))
    if kind == "isnull":
        return ("isnull", bool(node.neg), ast_key(node.operand))
    if kind == "in":
        return (
            "in",
            bool(node.neg),
            ast_key(node.operand),
            tuple(ast_key(item) for item in node.items),
        )
    if kind == "between":
        return (
            "between",
            bool(node.neg),
            ast_key(node.operand),
            ast_key(node.low),
            ast_key(node.high),
        )
    if kind == "like":
        return (
            "like",
            bool(node.neg),
            ast_key(node.operand),
            ast_key(node.pattern),
        )
    if kind == "func":
        return (
            "func",
            node.name.upper(),
            tuple(ast_key(arg) for arg in node.args),
        )
    if kind == "agg":
        return (
            "agg",
            node.name.upper(),
            None if node.arg is None else ast_key(node.arg),
        )
    raise QueryError("cannot compare expression")  # pragma: no cover

