"""Recursive-descent parser for the SQL subset in SPEC.md."""

from ._errors import QueryError
from ._lexer import tokenize
from ._nodes import Node, contains_agg

_AGGREGATES = frozenset({"COUNT", "SUM", "AVG", "MIN", "MAX"})
# Function name -> (minimum args, maximum args or None for unlimited)
_SCALARS = {
    "LOWER": (1, 1),
    "UPPER": (1, 1),
    "LENGTH": (1, 1),
    "ABS": (1, 1),
    "ROUND": (1, 2),
    "COALESCE": (1, None),
}


class Query:
    def __init__(
        self,
        sql,
        distinct,
        star,
        columns,
        table,
        where,
        group_by,
        having,
        order_by,
        limit,
        offset,
    ):
        self.sql = sql
        self.distinct = distinct
        self.star = star
        self.columns = columns
        self.table = table
        self.where = where
        self.group_by = group_by
        self.having = having
        self.order_by = order_by
        self.limit = limit
        self.offset = offset


def parse(sql):
    return _Parser(sql).parse_query()


class _Parser:
    def __init__(self, sql):
        self.sql = sql
        self.tokens = tokenize(sql)
        self.pos = 0

    # ------------------------------------------------------------------
    # Token helpers
    # ------------------------------------------------------------------
    def peek(self, ahead=0):
        index = self.pos + ahead
        if index >= len(self.tokens):
            return self.tokens[-1]
        return self.tokens[index]

    def advance(self):
        token = self.tokens[self.pos]
        if token.kind != "eof":
            self.pos += 1
        return token

    def at_op(self, *values):
        token = self.peek()
        return token.kind == "op" and token.value in values

    def accept_op(self, value):
        if self.at_op(value):
            self.advance()
            return True
        return False

    def expect_op(self, value):
        token = self.peek()
        if token.kind == "op" and token.value == value:
            return self.advance()
        self.error("expected %r" % value, token)

    def at_kw(self, value):
        token = self.peek()
        return token.kind == "kw" and token.value == value

    def accept_kw(self, value):
        if self.at_kw(value):
            self.advance()
            return True
        return False

    def expect_kw(self, value):
        token = self.peek()
        if token.kind == "kw" and token.value == value:
            return self.advance()
        self.error("expected %s" % value, token)

    def error(self, message, token=None):
        if token is None:
            token = self.peek()
        if token.kind == "eof":
            location = "at the end of the query"
        else:
            location = "at position %d" % token.start
        raise QueryError("%s %s" % (message, location))

    # ------------------------------------------------------------------
    # Query structure
    # ------------------------------------------------------------------
    def parse_query(self):
        self.expect_kw("SELECT")
        distinct = self.accept_kw("DISTINCT")

        star = False
        columns = []
        if self.at_op("*"):
            self.advance()
            star = True
        else:
            columns.append(self.parse_column())
            while self.accept_op(","):
                columns.append(self.parse_column())

        self.expect_kw("FROM")
        table = self.parse_name()

        where = None
        if self.accept_kw("WHERE"):
            where = self.parse_expr()

        group_by = []
        if self.accept_kw("GROUP"):
            self.expect_kw("BY")
            group_by.append(self.parse_expr())
            while self.accept_op(","):
                group_by.append(self.parse_expr())

        having = None
        if self.accept_kw("HAVING"):
            having = self.parse_expr()

        order_by = []
        if self.accept_kw("ORDER"):
            self.expect_kw("BY")
            order_by.append(self.parse_order_item())
            while self.accept_op(","):
                order_by.append(self.parse_order_item())

        limit = None
        offset = 0
        if self.accept_kw("LIMIT"):
            limit = self.parse_integer("LIMIT")
            if self.accept_kw("OFFSET"):
                offset = self.parse_integer("OFFSET")

        self.accept_op(";")
        if self.peek().kind != "eof":
            self.error("unexpected token")

        return Query(
            self.sql,
            distinct,
            star,
            columns,
            table,
            where,
            group_by,
            having,
            order_by,
            limit,
            offset,
        )

    def parse_column(self):
        expr = self.parse_expr()
        alias = None
        if self.accept_kw("AS"):
            alias = self.parse_name()
        elif self.peek().kind in ("ident", "qident"):
            alias = self.parse_name()
        return (expr, alias)

    def parse_order_item(self):
        expr = self.parse_expr()
        direction = 1
        if self.accept_kw("ASC"):
            direction = 1
        elif self.accept_kw("DESC"):
            direction = -1
        return (expr, direction)

    def parse_integer(self, clause):
        token = self.peek()
        if token.kind != "number" or "." in token.value:
            self.error("expected an integer after %s" % clause, token)
        self.advance()
        return int(token.value)

    def parse_name(self):
        token = self.peek()
        if token.kind in ("ident", "qident"):
            self.advance()
            return token.value
        if token.kind == "kw":
            self.error("keyword %s cannot be used as a name" % token.value, token)
        self.error("expected a name", token)

    # ------------------------------------------------------------------
    # Expressions
    # ------------------------------------------------------------------
    def parse_expr(self):
        return self.parse_or()

    def parse_or(self):
        left = self.parse_and()
        while self.accept_kw("OR"):
            right = self.parse_and()
            left = Node("or", left.start, right.end, left=left, right=right)
        return left

    def parse_and(self):
        left = self.parse_not()
        while self.accept_kw("AND"):
            right = self.parse_not()
            left = Node("and", left.start, right.end, left=left, right=right)
        return left

    def parse_not(self):
        token = self.peek()
        if self.accept_kw("NOT"):
            operand = self.parse_not()
            return Node("not", token.start, operand.end, operand=operand)
        return self.parse_comparison()

    def parse_comparison(self):
        left = self.parse_additive()
        token = self.peek()

        if token.kind == "kw" and token.value == "IS":
            self.advance()
            negated = self.accept_kw("NOT")
            self.expect_kw("NULL")
            return Node(
                "isnull",
                left.start,
                self.tokens[self.pos - 1].end,
                operand=left,
                neg=negated,
            )

        negated = False
        if token.kind == "kw" and token.value == "NOT":
            following = self.peek(1)
            if following.kind == "kw" and following.value in ("IN", "BETWEEN", "LIKE"):
                self.advance()
                negated = True
                token = self.peek()
            else:
                self.error("unexpected NOT", token)

        if token.kind == "kw" and token.value == "IN":
            self.advance()
            self.expect_op("(")
            items = [self.parse_expr()]
            while self.accept_op(","):
                items.append(self.parse_expr())
            closing = self.expect_op(")")
            return Node(
                "in",
                left.start,
                closing.end,
                operand=left,
                items=items,
                neg=negated,
            )

        if token.kind == "kw" and token.value == "BETWEEN":
            self.advance()
            low = self.parse_additive()
            self.expect_kw("AND")
            high = self.parse_additive()
            return Node(
                "between",
                left.start,
                high.end,
                operand=left,
                low=low,
                high=high,
                neg=negated,
            )

        if token.kind == "kw" and token.value == "LIKE":
            self.advance()
            pattern = self.parse_additive()
            return Node(
                "like",
                left.start,
                pattern.end,
                operand=left,
                pattern=pattern,
                neg=negated,
            )

        if negated:  # pragma: no cover - guarded above
            self.error("expected IN, BETWEEN, or LIKE", token)

        if token.kind == "op" and token.value in ("=", "!=", "<>", "<", "<=", ">", ">="):
            self.advance()
            right = self.parse_additive()
            operator = "!=" if token.value == "<>" else token.value
            return Node(
                "cmp",
                left.start,
                right.end,
                op=operator,
                left=left,
                right=right,
            )

        return left

    def parse_additive(self):
        left = self.parse_multiplicative()
        while self.at_op("+", "-", "||"):
            token = self.advance()
            right = self.parse_multiplicative()
            left = Node(
                "bin",
                left.start,
                right.end,
                op=token.value,
                left=left,
                right=right,
            )
        return left

    def parse_multiplicative(self):
        left = self.parse_unary()
        while self.at_op("*", "/"):
            token = self.advance()
            right = self.parse_unary()
            left = Node(
                "bin",
                left.start,
                right.end,
                op=token.value,
                left=left,
                right=right,
            )
        return left

    def parse_unary(self):
        token = self.peek()
        if token.kind == "op" and token.value == "-":
            self.advance()
            operand = self.parse_unary()
            return Node("neg", token.start, operand.end, operand=operand)
        return self.parse_primary()

    def parse_primary(self):
        token = self.peek()

        if token.kind == "number":
            self.advance()
            if "." in token.value:
                value = float(token.value)
            else:
                value = int(token.value)
            return Node("lit", token.start, token.end, value=value)

        if token.kind == "string":
            self.advance()
            return Node("lit", token.start, token.end, value=token.value)

        if token.kind == "kw" and token.value in ("NULL", "TRUE", "FALSE"):
            self.advance()
            if token.value == "NULL":
                value = None
            else:
                value = token.value == "TRUE"
            return Node("lit", token.start, token.end, value=value)

        if token.kind in ("ident", "qident"):
            self.advance()
            if token.kind == "ident" and self.at_op("("):
                return self.parse_call(token)
            return Node("col", token.start, token.end, name=token.value, index=None)

        if token.kind == "op" and token.value == "(":
            self.advance()
            inner = self.parse_expr()
            closing = self.expect_op(")")
            return Node("paren", token.start, closing.end, inner=inner)

        self.error("expected an expression", token)

    def parse_call(self, name_token):
        name = name_token.value
        upper = name.upper()
        self.expect_op("(")

        if self.at_op("*"):
            self.advance()
            closing = self.expect_op(")")
            if upper != "COUNT":
                self.error("function %s does not accept *" % name, name_token)
            if contains_agg(None):  # pragma: no cover - keeps symmetry
                pass
            return Node(
                "agg",
                name_token.start,
                closing.end,
                name="COUNT",
                arg=None,
            )

        args = []
        if not self.at_op(")"):
            args.append(self.parse_expr())
            while self.accept_op(","):
                args.append(self.parse_expr())
        closing = self.expect_op(")")

        if upper in _AGGREGATES:
            if len(args) != 1:
                self.error("%s takes exactly 1 argument" % upper, name_token)
            if contains_agg(args[0]):
                self.error("aggregate %s cannot be nested" % upper, name_token)
            return Node(
                "agg",
                name_token.start,
                closing.end,
                name=upper,
                arg=args[0],
            )

        if upper in _SCALARS:
            minimum, maximum = _SCALARS[upper]
            if len(args) < minimum or (maximum is not None and len(args) > maximum):
                self.error(
                    "%s takes the wrong number of arguments" % upper, name_token
                )
            return Node(
                "func",
                name_token.start,
                closing.end,
                name=upper,
                args=args,
            )

        self.error("unknown function %s" % name, name_token)

