    def parse_multiplicative(self):
        left = self.parse_unary()
        while self.at_op("*", "/"):
            token = self.advance()
            right = self.parse_unary()
            left = Node(
                "bin",
                left.start,
                right.end,
                op=token.value,
                left=left,
                right=right,
            )
        return left

    def parse_unary(self):
        token = self.peek()
        if token.kind == "op" and token.value == "-":
            self.advance()
            operand = self.parse_unary()
            return Node("neg", token.start, operand.end, operand=operand)
