"""Loading CSV tables and converting their fields."""

import csv
import os
import re

from ._errors import QueryError

_INTEGER = re.compile(r"-?[0-9]+\Z")
_DECIMAL = re.compile(r"-?(?:[0-9]+\.[0-9]*|[0-9]*\.[0-9]+)\Z")


def parse_field(text):
    """Convert one CSV field to a Python value."""
    if text == "":
        return None
    if _INTEGER.match(text):
        return int(text)
    if _DECIMAL.match(text):
        return float(text)
    return text


class Table:
    def __init__(self, columns, rows):
        self.columns = list(columns)
        self.rows = rows
        self._lookup = {}
        for index, name in enumerate(self.columns):
            self._lookup.setdefault(name.casefold(), index)

    def index(self, name):
        """Return the column index for ``name``, case-insensitively."""
        index = self._lookup.get(name.casefold())
        if index is None:
            raise QueryError("unknown column: %s" % name)
        return index

    @classmethod
    def load(cls, directory, name):
        path = os.path.join(directory, name + ".csv")
        try:
            with open(path, "r", encoding="utf-8", newline="") as handle:
                records = list(csv.reader(handle))
        except FileNotFoundError:
            raise QueryError("table not found: %s" % name)
        except OSError as exc:
            raise QueryError("cannot read table %s: %s" % (name, exc))
        except (csv.Error, UnicodeDecodeError) as exc:
            raise QueryError("cannot read table %s: %s" % (name, exc))

        if not records:
            raise QueryError("table %s is empty" % name)

        columns = records[0]
        width = len(columns)
        rows = []
        for record in records[1:]:
            if not record:
                continue
            values = [None] * width
            for index in range(min(width, len(record))):
                values[index] = parse_field(record[index])
            rows.append(values)

        return cls(columns, rows)

