"""Query preparation and evaluation."""

import re
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP, localcontext
from functools import cmp_to_key

from ._errors import QueryError
from ._nodes import Node, ast_key, children, contains_agg
from ._parser import parse
from ._table import Table

_AGGREGATES = frozenset({"COUNT", "SUM", "AVG", "MIN", "MAX"})


class Result:
    """The result of running a query."""

    def __init__(self, columns, rows):
        self.columns = columns
        self.rows = rows

    def __repr__(self):  # pragma: no cover - debugging aid
        return "Result(columns=%r, rows=%r)" % (self.columns, self.rows)


# ----------------------------------------------------------------------
# Values and comparisons
# ----------------------------------------------------------------------
def _is_number(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _type_name(value):
    if value is None:
        return "NULL"
    if isinstance(value, bool):
        return "a boolean"
    if isinstance(value, (int, float)):
        return "a number"
    if isinstance(value, str):
        return "a string"
    return type(value).__name__  # pragma: no cover


def _compare(left, right):
    if _is_number(left) and _is_number(right):
        if left < right:
            return -1
        if left > right:
            return 1
        return 0
    if isinstance(left, str) and isinstance(right, str):
        if left < right:
            return -1
        if left > right:
            return 1
        return 0
    if isinstance(left, bool) and isinstance(right, bool):
        if left is right:
            return 0
        return -1 if not left else 1
    raise QueryError(
        "cannot compare %s with %s" % (_type_name(left), _type_name(right))
    )


def _equal(left, right):
    return _compare(left, right) == 0


def _compare_op(operator, left, right):
    if left is None or right is None:
        return None
    comparison = _compare(left, right)
    if operator == "=":
        return comparison == 0
    if operator == "!=":
        return comparison != 0
    if operator == "<":
        return comparison < 0
    if operator == "<=":
        return comparison <= 0
    if operator == ">":
        return comparison > 0
    if operator == ">=":
        return comparison >= 0
    raise QueryError("unknown comparison operator %s" % operator)  # pragma: no cover


def _require_bool(value, operator):
    if value is None or isinstance(value, bool):
        return value
    raise QueryError(
        "%s requires boolean operands, not %s" % (operator, _type_name(value))
    )


def _and3(left, right):
    if left is False or right is False:
        return False
    if left is True and right is True:
        return True
    return None


def _or3(left, right):
    if left is True or right is True:
        return True
    if left is False and right is False:
        return False
    return None


def _not3(value):
    if value is None:
        return None
    return not value


def _arith(operator, left, right):
    if left is None or right is None:
        return None
    if not _is_number(left) or not _is_number(right):
        raise QueryError(
            "cannot apply %s to %s and %s"
            % (operator, _type_name(left), _type_name(right))
        )
    if operator == "/":
        if right == 0:
            return None
        return left / right
    if operator == "+":
        if isinstance(left, int) and isinstance(right, int):
            return left + right
        return left + right
    if operator == "-":
        if isinstance(left, int) and isinstance(right, int):
            return left - right
        return left - right
    if operator == "*":
        if isinstance(left, int) and isinstance(right, int):
            return left * right
        return left * right
    raise QueryError("unknown arithmetic operator %s" % operator)  # pragma: no cover


def _like_match(text, pattern):
    parts = []
    for character in pattern:
        if character == "%":
            parts.append(".*")
        elif character == "_":
            parts.append(".")
        else:
            parts.append(re.escape(character))
    return re.fullmatch("".join(parts), text, re.DOTALL) is not None


def _round_value(value, places):
    try:
        with localcontext() as context:
            context.prec = 200
            decimal = Decimal(str(value))
            if places is None:
                return int(
                    decimal.quantize(Decimal(1), rounding=ROUND_HALF_UP)
                )
            quantum = Decimal(1).scaleb(-places)
            return float(decimal.quantize(quantum, rounding=ROUND_HALF_UP))
    except (InvalidOperation, ValueError, OverflowError):
        raise QueryError("cannot round %r" % (value,))


def _hash_key(value):
    if value is None:
        return ("null",)
    if isinstance(value, bool):
        return ("bool", value)
    if isinstance(value, (int, float)):
        return ("number", value)
    if isinstance(value, str):
        return ("string", value)
    return ("other", repr(value))  # pragma: no cover


# ----------------------------------------------------------------------
# Evaluation contexts
# ----------------------------------------------------------------------
class _RowEnv:
    __slots__ = ("table", "row")

    def __init__(self, table, row):
        self.table = table
        self.row = row


class _GroupEnv:
    __slots__ = ("table", "rows")

    def __init__(self, table, rows):
        self.table = table
        self.rows = rows


def _current_row(env):
    if isinstance(env, _RowEnv):
        return env.row
    if env.rows:
        return env.rows[0]
    raise QueryError("cannot evaluate a column on an empty group")


# ----------------------------------------------------------------------
# Expression evaluation
# ----------------------------------------------------------------------
def _eval(node, env):
    kind = node.kind

    if kind == "lit":
        return node.value

    if kind == "col":
        return _current_row(env)[node.index]

    if kind == "paren":
        return _eval(node.inner, env)

    if kind == "neg":
        value = _eval(node.operand, env)
        if value is None:
            return None
        if not _is_number(value):
            raise QueryError("cannot negate %s" % _type_name(value))
        return -value

    if kind == "not":
        return _not3(_require_bool(_eval(node.operand, env), "NOT"))

    if kind == "and":
        left = _require_bool(_eval(node.left, env), "AND")
        if left is False:
            return False
        right = _require_bool(_eval(node.right, env), "AND")
        return _and3(left, right)

    if kind == "or":
        left = _require_bool(_eval(node.left, env), "OR")
        if left is True:
            return True
        right = _require_bool(_eval(node.right, env), "OR")
        return _or3(left, right)

    if kind == "bin":
        left = _eval(node.left, env)
        right = _eval(node.right, env)
        if node.op == "||":
            if left is None or right is None:
                return None
            return str(left) + str(right)
        return _arith(node.op, left, right)

    if kind == "cmp":
        left = _eval(node.left, env)
        right = _eval(node.right, env)
        return _compare_op(node.op, left, right)

    if kind == "isnull":
        value = _eval(node.operand, env)
        return (value is not None) if node.neg else (value is None)

    if kind == "in":
        value = _eval(node.operand, env)
        saw_null = False
        for item in node.items:
            candidate = _eval(item, env)
            if candidate is None:
                saw_null = True
                continue
            if value is None:
                continue
            if _equal(value, candidate):
                return not node.neg
        if value is None or saw_null:
            return None
        return True if node.neg else False

    if kind == "between":
        value = _eval(node.operand, env)
        low = _eval(node.low, env)
        high = _eval(node.high, env)
        outcome = _and3(
            _compare_op("<=", low, value),
            _compare_op("<=", value, high),
        )
        return _not3(outcome) if node.neg else outcome

    if kind == "like":
        value = _eval(node.operand, env)
        pattern = _eval(node.pattern, env)
        if value is None or pattern is None:
            return None
        if not isinstance(value, str) or not isinstance(pattern, str):
            raise QueryError("LIKE requires string operands")
        matched = _like_match(value, pattern)
        return (not matched) if node.neg else matched

    if kind == "func":
        return _eval_function(node, env)

    if kind == "agg":
        return _eval_aggregate(node, env)

    raise QueryError("cannot evaluate expression")  # pragma: no cover


def _eval_function(node, env):
    name = node.name

    if name == "COALESCE":
        for argument in node.args:
            value = _eval(argument, env)
            if value is not None:
                return value
        return None

    values = [_eval(argument, env) for argument in node.args]

    if name == "ROUND":
        value = values[0]
        if value is None:
            return None
        if not _is_number(value):
            raise QueryError("ROUND requires a number")
        if len(values) == 1:
            return _round_value(value, None)
        places = values[1]
        if places is None:
            return None
        if not isinstance(places, int) or isinstance(places, bool):
            raise QueryError("ROUND requires an integer number of places")
        return _round_value(value, places)

    if name in ("LOWER", "UPPER", "LENGTH"):
        value = values[0]
        if value is None:
            return None
        if not isinstance(value, str):
            raise QueryError("%s requires a string" % name)
        if name == "LOWER":
            return value.lower()
        if name == "UPPER":
            return value.upper()
        return len(value)

    if name == "ABS":
        value = values[0]
        if value is None:
            return None
        if not _is_number(value):
            raise QueryError("ABS requires a number")
        return abs(value)

    raise QueryError("unknown function %s" % name)  # pragma: no cover


def _eval_aggregate(node, env):
    if not isinstance(env, _GroupEnv):
        raise QueryError("aggregate %s used outside a grouped query" % node.name)

    rows = env.rows
    name = node.name

    if name == "COUNT":
        if node.arg is None:
            return len(rows)
        total = 0
        for row in rows:
            value = _eval(node.arg, _RowEnv(env.table, row))
            if value is not None:
                total += 1
        return total

    values = []
    for row in rows:
        value = _eval(node.arg, _RowEnv(env.table, row))
        if value is not None:
            values.append(value)

    if not values:
        return None

    if name in ("MIN", "MAX"):
        best = values[0]
        for value in values[1:]:
            comparison = _compare(value, best)
            if name == "MIN":
                if comparison < 0:
                    best = value
            else:
                if comparison > 0:
                    best = value
        return best

    for value in values:
        if not _is_number(value):
            raise QueryError("%s requires numbers" % name)

    if name == "SUM":
        return sum(values)
    if name == "AVG":
        return float(sum(values)) / len(values)

    raise QueryError("unknown aggregate %s" % name)  # pragma: no cover


# ----------------------------------------------------------------------
# Preparation
# ----------------------------------------------------------------------
def _resolve(node, table):
    if node is None:
        return
    if node.kind == "col":
        if node.index is None:
            node.index = table.index(node.name)
        return
    for child in children(node):
        _resolve(child, table)


def _prepare(query, table):
    if query.star:
        select_exprs = [
            (Node("col", 0, 0, name=name, index=index), None)
            for index, name in enumerate(table.columns)
        ]
    else:
        select_exprs = []
        for expression, alias in query.columns:
            _resolve(expression, table)
            select_exprs.append((expression, alias))

    output_names = []
    for expression, alias in select_exprs:
        if alias is not None:
            output_names.append(alias)
        elif expression.kind == "col":
            output_names.append(table.columns[expression.index])
        else:
            output_names.append(query.sql[expression.start : expression.end])

    _resolve(query.where, table)
    for expression in query.group_by:
        _resolve(expression, table)
    _resolve(query.having, table)

    order_items = []
    for expression, direction in query.order_by:
        target = None
        if expression.kind == "lit" and type(expression.value) is int:
            position = expression.value
            if position < 1 or position > len(output_names):
                raise QueryError(
                    "ORDER BY position %d is out of range" % position
                )
            target = position - 1
        elif expression.kind == "col":
            wanted = expression.name.casefold()
            for index, name in enumerate(output_names):
                if name.casefold() == wanted:
                    target = index
                    break
        if target is None:
            _resolve(expression, table)
            order_items.append((expression, direction))
        else:
            order_items.append((target, direction))

    if query.where is not None and contains_agg(query.where):
        raise QueryError("aggregates are not allowed in WHERE")
    for expression in query.group_by:
        if contains_agg(expression):
            raise QueryError("aggregates are not allowed in GROUP BY")

    grouped = bool(query.group_by)
    if not grouped:
        grouped = any(contains_agg(expression) for expression, _ in select_exprs)
    if not grouped and query.having is not None:
        grouped = contains_agg(query.having)
    if not grouped:
        grouped = any(
            isinstance(item, Node) and contains_agg(item)
            for item, _ in order_items
        )

    if grouped:
        group_keys = {ast_key(expression) for expression in query.group_by}

        def check(expression):
            if expression is None or expression.kind == "agg":
                return
            if ast_key(expression) in group_keys:
                return
