    query.select_exprs = select_exprs
    query.output_names = output_names
    query.order_items = order_items
    query.grouped = grouped


# ----------------------------------------------------------------------
# Execution
# ----------------------------------------------------------------------
def _execute(query, table):
    if query.where is None:
        filtered = list(table.rows)
    else:
        filtered = []
        for row in table.rows:
            if _eval(query.where, _RowEnv(table, row)) is True:
