            keyed.sort(key=cmp_to_key(compare_rows))

        pairs = [(values, env) for values, env in keyed]

    start = query.offset or 0
    if query.limit is not None:
        pairs = pairs[start : start + query.limit]
    elif start:
        pairs = pairs[start:]

    rows = [values for values, _ in pairs]
    return Result(list(query.output_names), rows)


